steps.script:
var PV = load("res://scripts/PlanValidator.gd")
var PM = load("res://scripts/PlanManager.gd")
PM.ensure_user_plans_dir()
var dir = DirAccess.open("user://ai_plans")
dir.list_dir_begin()
var f = dir.get_next()
while f != "":
	if f.ends_with(".json"):
		dir.remove(f)
	f = dir.get_next()
dir.list_dir_end()
var plan = PV.load_plan_file("res://tests/fixtures/ai_plans/fixture_a_c_test_crucible.json")
var path = "user://ai_plans/%s.json" % PM.slugify(str(plan.name))
var file = FileAccess.open(path, FileAccess.WRITE)
file.store_string(JSON.stringify(plan, "\t"))
file.close()
return path

var ui = tree.root.get_node("PlanSimulatorUI")
for i in range(ui._army_ids.size()):
	if str(ui._army_ids[i]) == "A_C_test":
		ui.army1_picker.selected = i
		ui.army2_picker.selected = i
for i in range(ui._zone_ids.size()):
	if str(ui._zone_ids[i]) == "crucible_of_battle":
		ui.zone_picker.selected = i
for i in range(ui._layout_ids.size()):
	if str(ui._layout_ids[i]) == "take_and_hold_mirror_1":
		ui.layout_picker.selected = i
ui._refresh_plan_pickers()
ui.games_spin.value = 2
# Player 1 takes the plan, player 2 takes none — the comparison the simulator
# exists to make.
ui.plan1_picker.selected = 1
ui.plan2_picker.selected = 0
var o = ui.build_run_options()
return "%s|%s|%s|%d|%s" % [str(o.army1), str(o.zone_id), str(o.layout_id), int(o.games),
	"plan" if str(o.plan1).ends_with(".json") else str(o.plan1)]

var ui = tree.root.get_node("PlanSimulatorUI")
for i in range(ui._army_ids.size()):
	if str(ui._army_ids[i]) == "A_C_test":
		ui.army1_picker.selected = i
		ui.army2_picker.selected = i
for i in range(ui._zone_ids.size()):
	if str(ui._zone_ids[i]) == "crucible_of_battle":
		ui.zone_picker.selected = i
for i in range(ui._layout_ids.size()):
	if str(ui._layout_ids[i]) == "take_and_hold_mirror_1":
		ui.layout_picker.selected = i
ui._refresh_plan_pickers()
ui.games_spin.value = 2
# Player 1 takes the plan, player 2 takes none — the comparison the simulator
# exists to make.
ui.plan1_picker.selected = 1
ui.plan2_picker.selected = 0
var o = ui.build_run_options()
return "%s|%s|%s|%d|%s" % [str(o.army1), str(o.zone_id), str(o.layout_id), int(o.games),
	"plan" if str(o.plan1).ends_with(".json") else str(o.plan1)]

var ui = tree.root.get_node("PlanSimulatorUI")
var item = ui.results_tree.get_root().get_first_child()
var out = []
while item != null:
	out.append("%s|%s|%s" % [item.get_text(0), item.get_text(1), item.get_text(2)])
	item = item.get_next()
return " ;; ".join(out)

var ui = tree.root.get_node("PlanSimulatorUI")
var path = str(PlanSimulator.last_summary.get("results_path", ""))
if path == "" or not FileAccess.file_exists(path):
	return "no results file"
var f = FileAccess.open(path, FileAccess.READ)
var data = JSON.parse_string(f.get_as_text())
f.close()
var games = data.get("games", [])
if games.size() != ui.row_count():
	return "row count %d vs file %d" % [ui.row_count(), games.size()]
var item = ui.results_tree.get_root().get_first_child()
var i = 0
while item != null:
	var g = games[i]
	if int(item.get_text(1)) != int(g.get("seed", -1)):
		return "row %d seed %s vs file %s" % [i, item.get_text(1), str(g.get("seed", ""))]
	if item.get_text(3) != "%d - %d" % [int(g.get("vp_p1", 0)), int(g.get("vp_p2", 0))]:
		return "row %d VP %s vs file %d-%d" % [i, item.get_text(3), int(g.get("vp_p1", 0)), int(g.get("vp_p2", 0))]
	item = item.get_next()
	i += 1
if str(data.get("summary", {}).get("headline", "")) != ui.summary_text():
	return "summary mismatch"
return "matches"

var ui = tree.root.get_node("PlanSimulatorUI")
var item = ui.results_tree.get_root().get_first_child()
var p1 = 0
var p2 = 0
while item != null:
	var parts = item.get_text(5).split(" / ")
	p1 += int(parts[0])
	p2 += int(parts[1])
	item = item.get_next()
return "%d,%d" % [p1, p2]

var ui = tree.root.get_node("PlanSimulatorUI")
var item = ui.results_tree.get_root().get_first_child()
var p2 = 0
while item != null:
	p2 += int(item.get_text(5).split(" / ")[1])
	item = item.get_next()
return p2

var ui = tree.root.get_node("PlanSimulatorUI")
var item = ui.results_tree.get_root().get_first_child()
var p1 = 0
while item != null:
	p1 += int(item.get_text(5).split(" / ")[0])
	item = item.get_next()
return p1
